pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(new Log()));
    }

    function _run(uint256 depositAmount, uint256 outAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > c.MinDeposit());
        vm.assume(outAmount > depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 recordedBefore;
        try c.balances(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        uint256 ethBefore = address(c).balance;
        try c.CashOut(outAmount) {} catch { return; }
        uint256 recordedAfter;
        try c.balances(address(this)) returns (uint256 __r) { recordedAfter = __r; } catch { return; }
        uint256 ethAfter = address(c).balance;
        assertTrue(recordedAfter == recordedBefore && ethAfter == ethBefore);
    }

    function testFuzz_run(uint256 depositAmount, uint256 outAmount) public {
        _run(depositAmount, outAmount);
    }

    receive() external payable {}
}

