contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 a1, uint256 a2) public payable {
        require(a1 > c.MinDeposit());
        require(a2 > c.MinDeposit());
        c.Deposit{value: a1}();
        c.Deposit{value: a2}();
        uint256 recorded = c.balances(address(this));
        assert(recorded == a1 + a2);
    }
    receive() external payable {}
}

