contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount <= c.MinDeposit());
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        c.Deposit{value: amount}();
        assert(c.balances(address(this)) == balBefore && address(c).balance == ethBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(depositAmount > c.MinDeposit());
        require(address(this).balance >= depositAmount);
        c.Deposit{value: depositAmount}();
        require(withdrawAmount <= c.balances(address(this)));
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        bool reverted;
        if (address(c).balance >= withdrawAmount) {
            try c.CashOut(withdrawAmount) { reverted = false; }
            catch { reverted = true; }
            if (!reverted) {
                assert(c.balances(address(this)) == balBefore - withdrawAmount &&
                       address(c).balance == ethBefore - withdrawAmount);
            } else {
                assert(c.balances(address(this)) == balBefore &&
                       address(c).balance == ethBefore);
            }
        } else {
            try c.CashOut(withdrawAmount) { reverted = false; }
            catch { reverted = true; }
            assert(reverted);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(depositAmount > c.MinDeposit());
        require(address(this).balance >= depositAmount);
        require(withdrawAmount <= depositAmount);
        c.Deposit{value: depositAmount}();
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        c.CashOut(withdrawAmount);
        assert(c.balances(address(this)) == balBefore - withdrawAmount &&
               address(c).balance == ethBefore - withdrawAmount &&
               balBefore == depositAmount);
    }
    receive() external payable {}
}

